import{_ as o,o as a,c as s,a0 as r}from"./chunks/framework.ChlVJx0I.js";const m=JSON.parse('{"title":"Embed codegraph in-process, not via daemon or CLI","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-embed-codegraph-in-process.md","filePath":"adr/0001-embed-codegraph-in-process.md","lastUpdated":1788385254000}'),n={name:"adr/0001-embed-codegraph-in-process.md"};function t(d,e,i,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="embed-codegraph-in-process-not-via-daemon-or-cli" tabindex="-1">Embed codegraph in-process, not via daemon or CLI <a class="header-anchor" href="#embed-codegraph-in-process-not-via-daemon-or-cli" aria-label="Permalink to &quot;Embed codegraph in-process, not via daemon or CLI&quot;">​</a></h1><p>The pi extension needs the codegraph query API and a file watcher for the lifetime of a pi session. We decided to embed the <code>@colbymchenry/codegraph</code> npm library directly in the pi process instead of talking to a codegraph daemon or shelling out to the <code>codegraph</code> CLI.</p><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><strong>In-process library embed (chosen).</strong> The package re-exports the full <code>CodeGraph</code> API for exactly this case. It runs on the host Node runtime (needs Node 22.5+ for <code>node:sqlite</code>; pi runs newer). The watcher lives in the session process, so freshness tracking has zero IPC. SQLite WAL plus codegraph&#39;s own <code>FileLock</code> make concurrent multi-session use safe.</li><li><strong>Attach to a codegraph daemon.</strong> The daemon exists to let many MCP clients share one long-lived index process. For a single in-process consumer it adds a process to manage (spawn, health, socket) for no gain.</li><li><strong>CLI subprocess per call.</strong> Needs a global install, pays process startup per query, and cannot hold a persistent watcher between calls.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The extension pins a codegraph version as an npm dependency (the per-platform package carries the Rust kernel and all tree-sitter WASM grammars, ~293 MB unpacked on linux-x64). Upgrades are a dependency bump.</li><li>Swapping the transport later (for example to a shared daemon) means re-plumbing every tool call and the watcher lifecycle. That is the lock-in this ADR records.</li></ul>',6)])])}const u=o(n,[["render",t]]);export{m as __pageData,u as default};
